with ranked as (select id, full_name, email, manager_id, job_title, hire_date, is_remote, level from employees qualify row_number() over (partition by dept_id, level order by hire_date, id) = 1) select date_trunc('year', hire_date) as year_start, count(distinct id) as distinct_ids, count_if(job_title = 'Analyst') as analyst_events from ranked group by date_trunc('year', hire_date)
